fn paethPredictor(
    mut a: c_uchar,
    mut b: c_uchar,
    mut c: c_uchar,
) -> c_uchar { {
    let mut pa: c_short =
        (if (b as c_int - c as c_int) < 0 as c_int {
            -(b as c_int - c as c_int)
        } else {
            b as c_int - c as c_int
        }) as c_short;
    let mut pb: c_short =
        (if (a as c_int - c as c_int) < 0 as c_int {
            -(a as c_int - c as c_int)
        } else {
            a as c_int - c as c_int
        }) as c_short;
    let mut pc: c_short = (if (a as c_int + b as c_int
        - c as c_int
        - c as c_int)
        < 0 as c_int
    {
        -(a as c_int + b as c_int
            - c as c_int
            - c as c_int)
    } else {
        a as c_int + b as c_int
            - c as c_int
            - c as c_int
    }) as c_short;
    if (pb as c_int) < pa as c_int {
        a = b;
        pa = pb;
    }
    return (if (pc as c_int) < pa as c_int {
        c as c_int
    } else {
        a as c_int
    }) as c_uchar;
} }

